      throw new Error(`Request timed out after ${timeoutMs}ms`);
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
}
```

### Usage with Options

```javascript
const name = await fetchUserName(123, {
  token: "your-auth-token",
  timeoutMs: 3000,
});
```

