      clearTimeout(timer);
    }
  };

  if (parallel) {
    // Fetch all URLs concurrently, results are returned in original order
    return Promise.all(urls.map(fetchStatus));
  } else {
    // Fetch URLs one at a time, sequentially
    const results = [];
    for (const url of urls) {
      results.push(await fetchStatus(url));
    }
    return results;
  }
}
```

