### Key Design Decisions

| Feature | Details |
|---|---|
| **`HEAD` request** | Avoids downloading response bodies, much more efficient |
| **`Promise.all`** | Fetches in parallel but preserves original array order |
| **`AbortController`** | Enables per-request timeout handling |
| **Error handling** | Network errors and timeouts are caught and returned gracefully (no thrown exceptions) |
| **Sequential mode** | Optional fallback for rate-limited APIs |

> **Note:** Some servers don't support `HEAD` requests and return a `405 Method Not Allowed`. In that case, switch `"HEAD"` to `"GET"` in the fetch call.

## Fetching URL Response Statuses

Here's a clean implementation that fetches multiple URLs and returns their response statuses in order:

```javascript
/**
 * Fetches multiple URLs and returns their response statuses in order.
 * @param {string[]} urls - Array of URLs to fetch
 * @param {Object} options - Optional configuration
 * @param {number} options.timeout - Request timeout in milliseconds (default: 5000)
 * @param {boolean} options.parallel - Fetch in parallel or sequentially (default: true)
 * @returns {Promise<Array<{url: string, status: number|null, statusText: string, error: string|null}>>}
 */
async function fetchResponseStatuses(urls, options = {}) {
  const { timeout = 5000, parallel = true } = options;

  const fetchWithTimeout = async (url) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(url, { signal: controller.signal });
      return {
        url,
        status: response.status,
        statusText: response.statusText,
        error: null,
      };
    } catch (error) {
      return {
        url,
        status: null,
        statusText: null,
        error: error.name === "AbortError" ? "Request timed out" : error.message,
      };
    } finally {
      clearTimeout(timer);
    }
  };

  if (parallel) {
    // Fetch all URLs simultaneously, preserving order with Promise.allSettled
    return Promise.all(urls.map((url) => fetchWithTimeout(url)));
  } else {
    // Fetch URLs one at a time, in order
    const results = [];
    for (const url of urls) {
      results.push(await fetchWithTimeout(url));
    }
    return results;
  }
}
```

