### Key Features

| Feature | Description |
|---|---|
| **Order preserved** | Results always match input URL order |
| **Timeout support** | Uses `AbortController` to cancel slow requests |
| **Error handling** | Network errors return `null` status with error message |
| **Parallel / Sequential** | Choose between speed or controlled request rate |
| **Non-throwing** | Never rejects — all errors are captured per-URL |

> **Note:** `fetch` follows redirects by default and returns the final status code. Pass `{ redirect: 'manual' }` to the fetch options if you need the redirect status (301/302).

## Fetching URL Response Statuses

Here's a clean implementation that fetches response statuses for a list of URLs while preserving order:

```javascript
/**
 * Fetches response statuses for a list of URLs in order
 * @param {string[]} urls - Array of URLs to fetch
 * @param {Object} options - Optional configuration
 * @param {number} options.timeout - Request timeout in milliseconds (default: 5000)
 * @param {number} options.retries - Number of retry attempts (default: 0)
 * @returns {Promise<Array>} - Array of status objects in the same order as input URLs
 */
async function fetchUrlStatuses(urls, options = {}) {
  const { timeout = 5000, retries = 0 } = options;

  if (!Array.isArray(urls)) {
    throw new TypeError("urls must be an array");
  }

  const fetchWithTimeout = (url, timeoutMs) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);

    return fetch(url, { signal: controller.signal }).finally(() =>
      clearTimeout(timer)
    );
  };

  const fetchWithRetry = async (url, attemptsLeft) => {
    try {
      const response = await fetchWithTimeout(url, timeout);
      return {
        url,
        status: response.status,
        statusText: response.statusText,
        ok: response.ok,
        error: null,
      };
    } catch (error) {
      if (attemptsLeft > 0) {
        return fetchWithRetry(url, attemptsLeft - 1);
      }

      return {
        url,
        status: null,
        statusText: null,
        ok: false,
        error: error.name === "AbortError" ? "Request timed out" : error.message,
      };
    }
  };

  // Use Promise.all to fetch concurrently while preserving order
  const results = await Promise.all(
    urls.map((url) => fetchWithRetry(url, retries))
  );

  return results;
}
```

