### Modern Solution (Recommended: `async/await`)

This approach is generally preferred for its readability, as it allows you to write asynchronous code that looks more like synchronous code.

```javascript
/**
 * Fetches a user from the API and returns their name.
 *
 * @param {number | string} userId The ID of the user to fetch.
 * @returns {Promise<string | null>} A promise that resolves to the user's name, or null if an error occurs.
 */
async function getUserName(userId) {
  try {
    // 1. Make the network request to the specific user endpoint.
    const response = await fetch(`/api/users/${userId}`);

    // 2. Check if the request was successful (status code 200-299).
    //    If not, throw an error to be caught by the catch block.
    if (!response.ok) {
      throw new Error(`HTTP error! Status: ${response.status}`);
    }

    // 3. Parse the JSON response body. This is also an async operation.
    const user = await response.json();

    // 4. Return the user's name.
    return user.name;

  } catch (error) {
    // 5. If any error occurred during the process, log it to the console.
    console.error('Could not fetch user:', error);

    // Return null or a default value to indicate failure.
    return null;
  }
}

// --- Example Usage ---
// You must use .then() or another async function to get the result.

// Using .then()
getUserName(1)
  .then(name => {
    if (name) {
      console.log(`User's name is: ${name}`); // Example output: "User's name is: Leanne Graham"
    } else {
      console.log('Failed to retrieve user name.');
    }
  });

// Or, inside another async function using await
async function displayUserName() {
  const name = await getUserName(2);
