 * Fetches a user from the API and returns their name.
 * @param {number | string} userId The ID of the user to fetch.
 * @returns {Promise<string|null>} A promise that resolves to the user's name, or null if an error occurs.
 */
async function getUserName(userId) {
  try {
    // 1. Make the network request to the API endpoint
    const response = await fetch(`/api/users/${userId}`);

    // 2. Check if the request was successful (status code 200-299)
