### The Function

This function is asynchronous and returns a promise that resolves with the parsed JSON data. It includes robust error handling for common issues like a missing file or invalid JSON content.

```javascript
import { readFile } from 'fs/promises';

/**
 * Asynchronously reads a JSON file from disk and parses it.
 *
 * @param {string} filePath The path to the JSON file.
 * @returns {Promise<any>} A promise that resolves with the parsed JSON data.
 * @throws {Error} Throws an error if the file cannot be read or if the JSON is invalid.
 */
async function readJsonFile(filePath) {
  try {
    // 1. Read the file content as a string, specifying 'utf8' encoding.
    // If you don't specify an encoding, readFile returns a Buffer.
    const fileContent = await readFile(filePath, 'utf8');

    // 2. Parse the string content into a JavaScript object.
    const data = JSON.parse(fileContent);

    // 3. Return the parsed data.
    return data;
  } catch (error) {
    // 4. Handle potential errors.
    if (error.code === 'ENOENT') {
      // Error: No such entity (file or directory)
      console.error(`Error: File not found at path: ${filePath}`);
    } else if (error instanceof SyntaxError) {
      // Error: The file content is not valid JSON
      console.error(`Error: Invalid JSON in file: ${filePath}. Details: ${error.message}`);
    } else {
      // Other potential errors (e.g., permissions)
      console.error(`An unexpected error occurred while reading the file:`, error);
    }
    // Re-throw the error to allow the calling code to handle it as well
    throw error;
  }
}

export { readJsonFile };
```

