### The Solution: Robust and Concurrent

This version is the recommended approach. It's fast, non-blocking, and handles errors gracefully for each individual URL.

```javascript
/**
 * Fetches a list of URLs concurrently and returns their response statuses in order.
 * This function handles network errors and HTTP error statuses (like 404 or 500).
 *
 * @param {string[]} urls - An array of URL strings to fetch.
 * @returns {Promise<Array<{url: string, status: number | string}>>} 
 *          A promise that resolves to an array of result objects.
 *          Each object contains the original URL and its status (a number)
 *          or an error message (a string).
 */
async function getResponseStatuses(urls) {
  // Create an array of promises by mapping over the URLs
  const promises = urls.map(async (url) => {
    try {
      // Use the HEAD method if you only need the status, as it's faster.
      // If a server doesn't support HEAD, you can fall back to GET.
      const response = await fetch(url, { method: 'HEAD' });
      return { url, status: response.status };
    } catch (error) {
      // This catches network errors (e.g., DNS resolution failure, no internet)
      // It also catches errors if the URL format is invalid.
      return { url, status: `ERROR: ${error.message}` };
    }
  });

  // Wait for all the promises to settle (either resolve or reject)
  // Promise.all will maintain the original order of the promises.
  return Promise.all(promises);
}

// --- Example Usage ---

const urlsToTest = [
  'https://www.google.com',
  'https://httpstat.us/404', // This URL returns a 404 Not Found
  'https://www.github.com',
  'https://httpstat.us/500', // This URL returns a 500 Internal Server Error
  'https://thissitedoesnotexist.invalid/', // This will cause a network error
  'https://developer.mozilla.org',
];

// Call the function and log the results
getResponseStatuses(urlsToTest)
  .then(statuses => {
    console.log('Response Statuses:');
    console.table(statuses);
  })
  .catch(error => {
    // This catch is for unexpected errors in the function itself,
    // not for individual fetch failures, which are handled inside.
    console.error('An unexpected error occurred:', error);
  });
```

