 * This function is robust and will not fail if one of the URLs is invalid or unreachable.
 *
 * @param {string[]} urls - An array of URL strings to fetch.
 * @returns {Promise<(number|string)[]>} A promise that resolves to an array of
 *   response statuses. A status will be a number (e.g., 200, 404) for a successful
 *   request, or an error string for a failed request.
 */
async function getUrlStatuses(urls) {
  // 1. Create an array of fetch promises.
  // We use .map() to transform each URL string into a fetch() promise.
  // These requests start running in parallel as soon as they are created.
  const promises = urls.map(url => fetch(url));

  // 2. Wait for all promises to complete (either succeed or fail).
  // Promise.allSettled() is perfect for this because it waits for all promises
  // and returns an array of result objects, never rejecting itself.
  const results = await Promise.allSettled(promises);

  // 3. Process the results to extract the status or error message.
  // The 'results' array is guaranteed to be in the same order as the 'promises' array.
  const statuses = results.map(result => {
    if (result.status === 'fulfilled') {
      // The request was successful, return the HTTP status code.
      // result.value is the Response object from fetch().
      return result.value.status;
    } else {
      // The request failed (e.g., network error, invalid domain).
      // result.reason is the Error object. We return a descriptive message.
      return `Error: ${result.reason.message}`;
    }
  });

  // 4. Return the final array of statuses.
  return statuses;
}

