```javascript
/**
 * Fetches an array of URLs and returns their HTTP response statuses in order.
 * Requests are sent in parallel for efficiency.
 *
 * @param {string[]} urls - An array of URL strings to fetch.
 * @returns {Promise<Array<number|string>>} A promise that resolves to an array 
 *   of status codes (e.g., 200, 404) or error messages for failed requests.
 */
async function getUrlStatuses(urls) {
